const b = $('Webhook uaZapi').first().json.body;
const cfg = $('Configuracao').first().json;
if (!b || typeof b !== 'object' || Array.isArray(b)) throw new Error('Webhook deve conter um objeto JSON de evento uaZapi.');
const event = String(b.EventType ?? b.event ?? b.eventType ?? '').toLowerCase();
if (!['messages','message'].includes(event)) return [];
const data = b.data && typeof b.data === 'object' ? b.data : {};
const m = b.message ?? data.message ?? (data.messageid || data.chatid ? data : null);
if (!m || Array.isArray(m)) throw new Error('Formato de mensagem uaZapi não reconhecido: esperado message ou data.message.');
const chat = b.chat ?? data.chat ?? {};
const bool = x => x === true || x === 'true' || x === 1;
const fromMe = bool(m.fromMe);
const chatId = String(m.chatid || chat.wa_chatid || '');
if (bool(m.wasSentByApi) || m.track_source === 'n8n-unificado' || bool(m.isGroup) || bool(chat.wa_isGroup) || /@(g\.us|newsletter|broadcast)$/.test(chatId)) return [];
if (!chatId || !/@(s\.whatsapp\.net|lid)$/.test(chatId)) throw new Error('chatid individual ausente ou inválido no evento.');
const id = String(m.messageid || m.id || '');
if (!id) throw new Error('Mensagem sem messageid/id. Não é seguro agrupar sem identificador.');
let c = m.content;
if (typeof c === 'string') { try { c = JSON.parse(c); } catch { c = { text: c }; } }
c = c && typeof c === 'object' ? c : {};
const rawType = String(m.messageType || m.type || '').toLowerCase();
let type = 'other';
if (/audio|ptt/.test(rawType)) type='audio';
else if (/image/.test(rawType)) type='image';
else if (/document|file/.test(rawType)) type='document';
else if (/video/.test(rawType)) type='video';
else if (/reaction|protocol|revoked|pollupdate/.test(rawType)) return [];
else if (/conversation|text|extendedtext|buttonsresponse|listresponse|interactive/.test(rawType)) type='text';
const content = String(m.text || c.text || c.caption || c.conversation || c.extendedTextMessage?.text || c.imageMessage?.caption || c.documentMessage?.caption || m.buttonOrListid || '');
if (type === 'other' && content.trim()) type='text';
if (type === 'text' && !content.trim()) return [];
// Um LID nunca é convertido em telefone. Em outgoing, sender_pn é o próprio dono.
const pn = [chat.phone, chat.wa_chatid, !fromMe ? m.sender_pn : '', chatId].find(x => x && !String(x).includes('@lid') && /^[+\d][\d+ :.-]*(?:@s\.whatsapp\.net)?$/.test(String(x)));
const digits = pn ? String(pn).split('@')[0].replace(/\D/g,'') : '';
const contactPhone = digits ? '+'+digits : '';
const assigned = String(chat.lead_assignedAttendant_id || '');
const human = Boolean(assigned && assigned !== String(cfg.ATENDENTE_IA_ID || '')) || Number(chat.chatbot_disableUntil || 0) > Date.now()/1000;
const testPhones = Array.isArray(cfg.TEST_PHONE_ALLOWLIST) ? cfg.TEST_PHONE_ALLOWLIST.map(x=>String(x).replace(/\D/g,'')) : [];
const resetCommand = content.trim().toLowerCase();
const resetAuthorized = !fromMe && digits && testPhones.includes(digits) && /^#reset(?:\s+ultimas2)?$/.test(resetCommand);
return [{json:{
  chat_id:chatId, message_id:id, messageType:type, content, contact_phone:contactPhone,
  contact_name:String(chat.lead_name || chat.name || chat.wa_contactName || (!fromMe ? m.senderName : '') || chat.wa_name || 'Contato'),
  session_key:String(cfg.INSTANCE_KEY)+':'+chatId,
  incoming_outgoing:fromMe?'outgoing':'incoming', human_assigned:human,
  reset_authorized:Boolean(resetAuthorized), reset_mode:resetCommand.endsWith('ultimas2')?'ultimas2':'tudo',
  email:String(chat.lead_email||''), funil:cfg.FUNIL, lancamento:cfg.LANCAMENTO, segmentacao:cfg.SEGMENTACAO,
  template_name:cfg.TEMPLATE_NAME, qual_webn:cfg.QUAL_WEBN,
  created_at:new Date().toISOString(), source_id:digits || chatId,
  raw_type:rawType, file_name:String(c.fileName || c.documentMessage?.fileName || '')
}}];

